%[text] # Visually inspect buildElevationProfileFromRoadGradeProfileData
BaseRoadGradePercent = [ 0 0 0, -5 -5 -5, 0 0 0, 2 2 2, 0 0 0 ];

BaseHorizontalDistance = simscape.Value([ 0 50 100, 200 250 300, 400 450 500, 600 650 700, 800 850 900 ], "ft");
horizontal_length_unit = string(unit(BaseHorizontalDistance));

InterpolationMethod = "smooth";
InterpolationInterval = simscape.Value(0.05, horizontal_length_unit);

LeftElevation = simscape.Value(10, "m");
vertical_length_unit = string(unit(LeftElevation));

% !inspection-target
refined_data = buildElevationProfileFromRoadGradeProfileData( ...
  value(BaseHorizontalDistance), ...
  BaseRoadGradePercent, ...
  InterpolationMethod, ...
  value(LeftElevation), ...
  value(InterpolationInterval, horizontal_length_unit) );

plotElevationAndRoadGradeProfiles( ... %[output:group:7cdb1d25] %[output:1cf905e3]
  DataSource = "direct", ... %[output:1cf905e3]
  BaseHorizontalDistance = BaseHorizontalDistance, ... %[output:1cf905e3]
  BaseGradePercent = BaseRoadGradePercent, ... %[output:1cf905e3]
  RefinedHorizontalDistance = simscape.Value(transpose(refined_data.x), horizontal_length_unit), ... %[output:1cf905e3]
  RefinedGradePercent = refined_data.grade, ... %[output:1cf905e3]
  RefinedElevation = simscape.Value(transpose(refined_data.z), vertical_length_unit) ) %[output:group:7cdb1d25] %[output:1cf905e3]
